<?php require __DIR__.'/inc/page_helpers.php';$id=(int)($_GET['id']??($currentUser['id']??0));$q=$db->prepare('SELECT * FROM users WHERE id=?');$q->execute([$id]);$profile=$q->fetch();$owned=[];if($profile){$q=$db->prepare('SELECT c.id,c.name,c.type FROM inventory i JOIN catalog_items c ON c.id=i.item_id WHERE i.user_id=?');$q->execute([$id]);$owned=$q->fetchAll();}page_start($profile?$profile['username']:'User not found');?><section class="Panel"><?php if(!$profile):?><h1>User not found</h1><?php else:?><h1><?=e($profile['username'])?></h1><p><?=nl2br(e($profile['blurb']))?></p><p>Joined <?=e($profile['created_at'])?></p><h2>Inventory</h2><?php foreach($owned as $i):?><p><a href="/Item.php?id=<?=(int)$i['id']?>"><?=e($i['name'])?></a> (<?=e($i['type'])?>)</p><?php endforeach;?><?php if(!$owned):?><p>No items yet.</p><?php endif;?><?php endif;?></section><?php page_end();